<?php
require_once __DIR__.'/portal.php';
require_once __DIR__.'/clearance_logic.php';
function rmmc_clearance_period():array{
    $terms=rmmc_all("SELECT DISTINCT school_year,semester FROM events WHERE school_year <> '' AND semester <> '' ORDER BY school_year DESC,semester DESC LIMIT 20");
    $year=(string)($_GET['school_year']??($terms[0]['school_year']??''));$sem=(string)($_GET['semester']??($terms[0]['semester']??''));
    return [$year,$sem,$terms];
}
function rmmc_clearance_staff(string $role):void{
    rmmc_require_roles($role);[$year,$sem,$terms]=rmmc_clearance_period();
    $view=(int)($_GET['student']??0);
    $students=$view ? rmmc_all('SELECT * FROM students WHERE id=?','i',[$view]) : rmmc_all('SELECT * FROM students ORDER BY lastname,firstname LIMIT 200');
    rmmc_shell_start('Clearance',$role);
    ?><div class="welcome"><h1>Semester clearance</h1><p>Check ITE and COMSOC required attendance and fines before approving clearance.</p></div><section class="panel"><form class="filters" method="get"><div class="field"><label>Academic year</label><input name="school_year" value="<?=rmmc_e($year)?>" required></div><div class="field"><label>Semester</label><input name="semester" value="<?=rmmc_e($sem)?>" required></div><button>View period</button></form><?php if(!rmmc_new_ledger_available()):?><div class="notice error">The new clearance ledger is not installed. Run the additive migration before approving clearance.</div><?php endif;?><div class="table-scroll"><table class="data-table"><tr><th>Student</th><th>Course</th><th>Year</th><th>Outstanding</th><th>Status</th><th>Details</th></tr><?php foreach($students as $st): $state=rmmc_clearance_status($st,$year,$sem);?><tr><td><?=rmmc_e($st['lastname'].', '.$st['firstname'])?><br><small><?=rmmc_e($st['student_number'])?></small></td><td><?=rmmc_e($st['course'])?></td><td><?=rmmc_e($st['year_level'])?></td><td>₱<?=number_format($state['due'],2)?></td><td><?=rmmc_badge($state['status'])?></td><td><a href="?<?=http_build_query(['student'=>$st['id'],'school_year'=>$year,'semester'=>$sem])?>">Review →</a></td></tr><?php endforeach;?></table></div><?php if(!$students):?><p class="empty">No enrolled students found.</p><?php endif;?></section>
    <?php if($view&&$students):$st=$students[0];$state=rmmc_clearance_status($st,$year,$sem); ?><section class="panel"><h2>Requirements for <?=rmmc_e($st['firstname'].' '.$st['lastname'])?></h2><?php if($state['blockers']):?><ul><?php foreach($state['blockers'] as $b):?><li><?=rmmc_e($b)?></li><?php endforeach;?></ul><?php else:?><p>No unresolved required event attendance or fines found for this period.</p><?php endif; ?><?php if($state['status']==='Pending Approval'):?><form action="clearance_action.php" method="post"><input type="hidden" name="csrf" value="<?=rmmc_e(rmmc_csrf())?>"><input type="hidden" name="student_id" value="<?=$view?>"><input type="hidden" name="school_year" value="<?=rmmc_e($year)?>"><input type="hidden" name="semester" value="<?=rmmc_e($sem)?>"><button>Approve clearance</button></form><?php endif; ?><?php if($state['status']==='Cleared'):?><p class="notice success">Approved <?=rmmc_e($state['approved']['approved_at']??'')?></p><?php endif; ?></section><?php endif; ?><?php rmmc_shell_end();
}
function rmmc_clearance_student():void {
    rmmc_require_roles('Student');$st=rmmc_student();if(!$st){http_response_code(404);exit('No profile');}
    [$year,$sem,$terms]=rmmc_clearance_period();$state=rmmc_clearance_status($st,$year,$sem);
    rmmc_shell_start('My Clearance','Student');?><div class="welcome"><h1>My semester clearance</h1><p>Review your required ITE and COMSOC events and outstanding financial obligations.</p></div><section class="panel"><form class="filters" method="get"><div class="field"><label>Academic year</label><input name="school_year" value="<?=rmmc_e($year)?>"></div><div class="field"><label>Semester</label><input name="semester" value="<?=rmmc_e($sem)?>"></div><button>View</button></form><h2><?=rmmc_badge($state['status'])?></h2><p>Outstanding balance: <strong>₱<?=number_format($state['due'],2)?></strong></p><?php if($state['blockers']):?><h3>Pending requirements</h3><ul><?php foreach($state['blockers'] as $b):?><li><?=rmmc_e($b)?></li><?php endforeach;?></ul><?php elseif($state['status']==='Pending Approval'):?><p>Requirements satisfied. Officer approval is still pending.</p><?php elseif($state['status']==='Cleared'):?><p>Requirements satisfied and clearance approved.</p><?php endif;?></section><?php rmmc_shell_end();
}
